// AUTO-GENERATED by scripts/og-images.mjs — do not edit by hand.
import fs from 'fs';
import path from 'path';
import { fileURLToPath, pathToFileURL } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const ROOT = path.join(__dirname, '..');
const PUBLIC = path.join(ROOT, 'public');
const OG_DIR = path.join(PUBLIC, 'og');
const load = (rel) => import(pathToFileURL(path.join(ROOT, rel)).href);

const { movieDatabase } = await load('src/data/movies.js');
const { DEAD_IDS } = await load('src/data/dead-links.js');
const { DUPLICATE_TO_CANONICAL } = await load('src/data/duplicates.js');
const { posterFor } = await load('src/lib/posters.js');
const { OG_SIZE, OG_DEFAULT } = await load('src/lib/og.js');

async function main() {
    const { default: sharp } = await import('sharp');

    if (!fs.existsSync(OG_DIR)) fs.mkdirSync(OG_DIR, { recursive: true });

    const live = movieDatabase.filter(
        (m) => !DEAD_IDS.has(m.id) && !DUPLICATE_TO_CANONICAL[m.id],
    );

    const posterId = (m) => {
        const p = posterFor(m);
        return p && !p.startsWith('http') ? path.join(PUBLIC, p.slice(1)) : null;
    };

    let done = 0;
    let skipped = 0;
    for (const m of live) {
        const poster = posterId(m);
        const out = path.join(OG_DIR, `${m.id}.jpg`);
        if (!poster) {
            skipped++;
            continue;
        }
        if (!fs.existsSync(poster)) {
            skipped++;
            continue;
        }
        try {
            await sharp(poster)
                .resize(OG_SIZE.w, OG_SIZE.h, { fit: 'cover', position: 'centre' })
                .jpeg({ quality: 80 })
                .toFile(out);
            done++;
        } catch (e) {
            skipped++;
        }
    }

    // Default card: dark grey rectangle (1200×630). Titles without poster fall back to this.
    const defaultPath = path.join(OG_DIR, 'default.jpg');
    if (!fs.existsSync(defaultPath)) {
        await sharp({
            create: { width: OG_SIZE.w, height: OG_SIZE.h, channels: 3, background: { r: 17, g: 17, b: 24 } },
        })
            .jpeg({ quality: 80 })
            .toFile(defaultPath);
    }

    console.log(`OG cards: ${done} made, ${skipped} skipped (no poster), default written`);
}

const args = process.argv.slice(2);
if (args.includes('--selftest')) {
    console.log('OG_SIZE:', JSON.stringify(OG_SIZE));
    console.log('OG_DEFAULT:', OG_DEFAULT);
    process.exit(0);
}
main().catch((e) => {
    console.error(e);
    process.exit(1);
});
